sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    /**
     * Clears extra route parameters from the current navigation state.
     * 
     * Resets extraParams to null, typically used after consuming URL parameters
     * or when navigating away from a context that required additional routing data.
     */

    helpers.navigate.setRouteParams({
        params: { extraParams: null }
    });
}
